// @generated by:gauntlet run:godseye-audit-r1-r4
import { randomUUID } from "node:crypto";
import { FoundationEngine, InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { gateAdmission } from "../packages/core/src/infra-admission.js";
import { defaultHeavyPolicy, heavySlotFree } from "../packages/core/src/infra-heavy.js";
import { closeFixture, type FoundationFixture, foundationFixture } from "./foundations-helpers.js";

describe("T05 T37 heavy admission after approval expiry (audit R3)", () => {
  let fixture: FoundationFixture;
  let engine: FoundationEngine;
  const APPROVAL_MS = 300_000;
  const policy = { ...defaultHeavyPolicy(), maxConcurrent: 1, maxQueued: 1 };
  beforeEach(async () => {
    fixture = await foundationFixture();
    engine = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      adapters: [fixture.provider.adapter],
      approvalMs: APPROVAL_MS,
      approvalPolicy: () => true,
      admission: (tx, plan, runId) => gateAdmission(policy, tx, plan.command, runId),
      // Requeue must repeat capacity admission without reserving provider resources again.
      requeueAdmission: (tx, plan, runId) => gateAdmission(policy, tx, plan.command, runId),
      claimGate: (tx, plan, runId) => heavySlotFree(tx, policy, plan.command, runId),
    });
  });
  afterEach(async () => {
    await closeFixture(fixture);
  });
  async function enqueueHeavy() {
    const resource = await engine.registerResource(
      fixture.freshOwner(),
      {
        projectId: fixture.project.id,
        environmentId: fixture.development.id,
        kind: "database-plan",
        name: `Heavy fixture ${randomUUID()}`,
      },
      randomUUID(),
    );
    const plan = await engine.createPlan(
      fixture.freshOwner(),
      {
        ...fixture.planInput,
        command: { kind: "database.operation", intent: "backup", planRef: resource.id },
        maxCostMicros: 1,
      },
      randomUUID(),
    );
    await engine.approve(fixture.freshOwner(), plan.id, plan.hash, randomUUID());
    const run = await engine.enqueue(fixture.freshOwner(), plan.id, randomUUID());
    return { plan, run };
  }
  async function expiredThenFilled() {
    const waiting = await enqueueHeavy();
    fixture.clock.advance(APPROVAL_MS + 1);
    expect(await engine.claim("approval-expiry-worker")).toBeNull();
    expect((await engine.getRun(fixture.freshOwner(), waiting.run.id)).status).toBe(
      "awaiting_approval",
    );
    const first = await enqueueHeavy();
    const second = await enqueueHeavy();
    return { waiting, first, second };
  }

  it("refuses approval renewal atomically when the heavy queue filled during approval expiry", async () => {
    const { waiting } = await expiredThenFilled();
    const before = await fixture.store.db
      .select()
      .from(schema.approvals)
      .where(eq(schema.approvals.planId, waiting.plan.id));
    const auditBefore = await fixture.store.db.select().from(schema.audit);
    const budgetBefore = await engine.getBudget(fixture.freshOwner(), fixture.project.id);
    const renewalKey = randomUUID();

    await expect(
      engine.approve(fixture.freshOwner(), waiting.plan.id, waiting.plan.hash, renewalKey),
    ).rejects.toMatchObject({ code: "HEAVY_QUEUE_FULL", status: 429 });

    expect((await engine.getRun(fixture.freshOwner(), waiting.run.id)).status).toBe(
      "awaiting_approval",
    );
    expect(
      await fixture.store.db
        .select()
        .from(schema.approvals)
        .where(eq(schema.approvals.planId, waiting.plan.id)),
    ).toEqual(before);
    expect(await fixture.store.db.select().from(schema.audit)).toEqual(auditBefore);
    expect(await engine.getBudget(fixture.freshOwner(), fixture.project.id)).toEqual(budgetBefore);
    expect(
      await fixture.store.db
        .select()
        .from(schema.foundationRequests)
        .where(eq(schema.foundationRequests.key, renewalKey)),
    ).toHaveLength(0);

    const queued = (await engine.listRuns(fixture.freshOwner())).find(
      (run) => run.status === "queued",
    );
    if (!queued) throw new Error("Expected a capacity-holding queued run");
    await engine.cancel(fixture.freshOwner(), queued.id, randomUUID());
    await engine.approve(fixture.freshOwner(), waiting.plan.id, waiting.plan.hash, renewalKey);
    expect((await engine.getRun(fixture.freshOwner(), waiting.run.id)).status).toBe("queued");
  });

  it("permits one renewed admission after capacity is freed and replays it idempotently", async () => {
    const { waiting, first } = await expiredThenFilled();
    await engine.cancel(fixture.freshOwner(), first.run.id, randomUUID());
    const renewalKey = randomUUID();
    await engine.approve(fixture.freshOwner(), waiting.plan.id, waiting.plan.hash, renewalKey);
    const beforeReplay = await engine.getRun(fixture.freshOwner(), waiting.run.id);

    await engine.approve(fixture.freshOwner(), waiting.plan.id, waiting.plan.hash, renewalKey);

    expect(await engine.getRun(fixture.freshOwner(), waiting.run.id)).toEqual(beforeReplay);
    expect(beforeReplay.status).toBe("queued");
    expect(
      (await engine.listRuns(fixture.freshOwner())).filter((run) => run.status === "queued"),
    ).toHaveLength(policy.maxConcurrent + policy.maxQueued);
  });

  it("enforces the same renewed heavy admission through the production Infrastructure composition", async () => {
    const infrastructure = new InfrastructureEngine(fixture.store, {
      now: fixture.clock.now,
      heavyTasks: { maxConcurrent: 1, maxQueued: 1 },
      jobs: { handlers: new Map() },
    });
    const production = infrastructure.foundation;
    async function createRestore() {
      const resource = await production.registerResource(
        fixture.freshOwner(),
        {
          projectId: fixture.project.id,
          environmentId: fixture.production.id,
          kind: "database-plan",
          name: `Renewal fixture ${randomUUID()}`,
        },
        randomUUID(),
      );
      const plan = await production.createPlan(
        fixture.freshOwner(),
        {
          ...fixture.planInput,
          environmentId: fixture.production.id,
          targetId: fixture.production.id,
          adapterId: "local.jobs",
          command: { kind: "database.operation", intent: "restore", planRef: resource.id },
          maxCostMicros: 1,
        },
        randomUUID(),
      );
      await production.approve(fixture.freshOwner(), plan.id, plan.hash, randomUUID());
      const run = await production.enqueue(fixture.freshOwner(), plan.id, randomUUID());
      return { plan, run };
    }
    // Only the shared admission contract is exercised; no restore or handler is executed.
    const waiting = await createRestore();
    fixture.clock.advance(3_600_001);
    expect(await production.claim("composed-expiry-worker")).toBeNull();
    await createRestore();
    await createRestore();

    await expect(
      production.approve(fixture.freshOwner(), waiting.plan.id, waiting.plan.hash, randomUUID()),
    ).rejects.toMatchObject({ code: "HEAVY_QUEUE_FULL", status: 429 });
    expect((await production.getRun(fixture.freshOwner(), waiting.run.id)).status).toBe(
      "awaiting_approval",
    );
  });
});
